import re

_FENCE_LINE_PATTERN = re.compile('^\\s*(`{3,}|~{3,})')

EVIDENCE_SOURCE_OCC_PR_PATTERN = re.compile('^Evidence-Source: OCC#(\\d+)$', re.IGNORECASE | re.MULTILINE)

EVIDENCE_SOURCE_SHA_PATTERN = re.compile('^Evidence-Source: ([0-9a-f]{7,40})$', re.IGNORECASE | re.MULTILINE)

def strip_noncanonical_regions(pr_body):
    out: list[str] = []
    in_fence = False
    fence_char = ''
    for line in pr_body.splitlines():
        fence = _FENCE_LINE_PATTERN.match(line)
        if fence is not None:
            marker_char = fence.group(1)[0]
            if not in_fence:
                in_fence = True
                fence_char = marker_char
            elif marker_char == fence_char:
                in_fence = False
                fence_char = ''
            out.append('')
            continue
        if in_fence:
            out.append('')
            continue
        if line.lstrip().startswith('>'):
            out.append('')
            continue
        out.append(line)
    return '\n'.join(out)

def parse_evidence_source(pr_body):
    for line in strip_noncanonical_regions(pr_body).splitlines():
        if not line.lower().startswith('evidence-source:'):
            continue
        if (m_pr := EVIDENCE_SOURCE_OCC_PR_PATTERN.fullmatch(line)):
            return (m_pr.group(1), None)
        if (m_sha := EVIDENCE_SOURCE_SHA_PATTERN.fullmatch(line)):
            return (None, m_sha.group(1))
        break
    return (None, None)
